SELECT commit_id, repo_id, commit_status, commit_source, created_by, published_by, created_at, published_at, comment, meta
FROM public.artifact_commit
WHERE repo_id = #{query.repoId}

    AND commit_status = #{query.commitStatusOrNull}


    AND commit_source = #{query.commitSourceOrNull}

ORDER BY ${query.sortByOrDefault} ${query.sortOrderOrDefault}
LIMIT #{query.limit} OFFSET #{query.offset}

SELECT COUNT(*)
FROM public.artifact_commit
WHERE repo_id = #{query.repoId}

    AND commit_status = #{query.commitStatusOrNull}


    AND commit_source = #{query.commitSourceOrNull}

SELECT commit_id, repo_id, commit_status, commit_source, created_by, published_by, created_at, published_at, comment, meta
