  AND commit_id = #{commitId}

mapper.update:
UPDATE public.artifact_commit
SET commit_status = 'PUBLISHED',
    published_at = now(),
    published_by = #{publishedBy},
    comment = #{comment}
WHERE repo_id = #{repoId}
  AND commit_id = #{commitId}
  AND commit_status = 'DRAFT'

